import {makeBook} from './book-template.mjs';

// Original illustration for the fictional example; no family photos are bundled.
const illustration = `<svg xmlns="http://www.w3.org/2000/svg" width="720" height="460" viewBox="0 0 720 460"><rect width="720" height="460" fill="#ead8bd"/><circle cx="566" cy="101" r="51" fill="#fff1cc"/><path d="M0 280L160 139l171 156 123-104 266 114v155H0" fill="#b3b7a0"/><path d="M0 338q180-88 365 2t355-20v140H0" fill="#858f79"/><path d="M201 460l160-154h68l149 154" fill="#d5bd98"/><rect x="250" y="222" width="244" height="166" rx="20" fill="#426e84" stroke="#304e60" stroke-width="8"/><path d="M331 221v-24q0-17 17-17h46q17 0 17 17v24" fill="none" stroke="#304e60" stroke-width="12"/><path d="M292 226v157m158-157v157" stroke="#dcad74" stroke-width="15"/><rect x="358" y="273" width="40" height="32" rx="4" fill="#e9cda0"/><path d="M369 289h18" stroke="#6e5944" stroke-width="4"/></svg>`;
const imageUrl = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(illustration)}`;
export function bookPreview(){return `<figure class="book-showcase" aria-label="Illustrated example of a finished family storybook"><div class="example-spread"><div class="example-cover"><span>STORIES WE KEEP</span><img src="${imageUrl}" alt="Illustration of a blue suitcase on a country road" width="720" height="460"><h2>The blue<br>suitcase</h2><p>A memory of a new beginning</p><small>A family memory, kept close.</small></div><div class="example-page"><span>THE BLUE SUITCASE · ENGLISH</span><p>“When I was seventeen, I moved from my village to the city. My aunt met me at the bus station.”</p><div class="example-page-note">Your words.<br>Your pictures.<br>A memory to return to.</div><small>1</small></div></div><figcaption>Fictional story &amp; sample illustration. Add your own family photos.</figcaption></figure>`}
export function storySteps(){return `<section class="story-steps" aria-labelledby="storyStepsTitle"><h2 id="storyStepsTitle">From their voice to a book you can keep.</h2><ol><li><span>01</span><h3>Record</h3><p>Tell a memory in Amharic or English, or upload a recording.</p></li><li><span>02</span><h3>Review</h3><p>Read the transcript. Make sure names and details feel right.</p></li><li><span>03</span><h3>Add photos</h3><p>Choose <strong>Create my storybook</strong>. Add pictures and captions to the cover and pages.</p></li><li><span>04</span><h3>Keep it your way</h3><p>Save on this device. Download a digital book or PDF whenever you want.</p></li></ol><p class="steps-note">Downloading is optional. Digital books include your attached recording; PDFs include text and pictures.</p></section>`}
let picture;
export async function illustratedExample(story){
  if(!picture){const image=new Image();image.src=imageUrl;await image.decode();const canvas=document.createElement('canvas');canvas.width=720;canvas.height=460;canvas.getContext('2d').drawImage(image,0,0);picture=canvas.toDataURL('image/png')}
  const book=makeBook(story);book.photo=picture;book.dedication='A fictional example. Replace this illustration with a photo of your own.';
  book.pages[0].photo=picture;book.pages[0].caption='The blue suitcase — sample illustration';return book;
}
